def function_spans(lines):
    spans = []
    i, n = 0, len(lines)
    header_re = re.compile(r"^[A-Za-z_][\w\s\*,\(\)\[\]]*\(.*$")
    while i < n:
        line = lines[i]
        if header_re.match(line) and not line.startswith(("if","for","while","switch","return")):
            depth = 0
            started = False
            j = i
            end = None
            while j < n and j < i + 3000:
