                    if ch == '{':
                        depth += 1; started = True
                    elif ch == '}':
                        depth -= 1
                        if started and depth == 0:
                            end = j
                            break
                if end is not None:
                    break
                j += 1
            if end is not None:
                spans.append((i, end))
                i = end + 1
                continue
        i += 1
    return spans

results = []
for dirpath, dirs, files in os.walk(ROOT):
    dirs[:] = [d for d in dirs if d not in (".git",)]
    for f in files:
        if not f.endswith(".c"):
